"""Pydantic v2 schemas for structured Gemini outputs and agent data."""

from __future__ import annotations

from typing import Literal

from pydantic import BaseModel, ConfigDict, Field


class ReviewFinding(BaseModel):
    """Structured code review finding generated by Gemini."""

    model_config = ConfigDict(frozen=True)

    file_path: str = Field(description="Relative path of the reviewed file.")
    line: int = Field(default=1, description="Line number of the issue in the head file.")
    severity: Literal["info", "minor", "major", "critical"] = Field(
        default="minor", description="Severity level of the finding."
    )
    category: Literal["bug", "security", "performance", "style", "maintainability"] = Field(
        default="bug", description="Category of the finding."
    )
    confidence: float = Field(
        default=0.8,
        ge=0.0,
        le=1.0,
        description="Confidence score between 0.0 and 1.0 that this is a real issue.",
    )
    title: str = Field(description="Short one-line summary of the bug or flaw.")
    explanation: str = Field(description="Detailed explanation with rationale.")
    reproducible: bool = Field(
        default=False,
        description="Whether this issue can be reproduced with an isolated pytest unit test.",
    )


class ReviewResponse(BaseModel):
    """Overall review output containing a list of findings."""

    model_config = ConfigDict(frozen=True)

    findings: list[ReviewFinding] = Field(
        default_factory=list, description="List of identified issues/findings."
    )
    summary: str = Field(default="", description="High-level review summary.")


class ReproductionTestPlan(BaseModel):
    """Structured plan and pytest code reproducing a suspected bug."""

    model_config = ConfigDict(frozen=True)

    target_finding_idx: int = Field(
        default=0, description="Index of the finding this test reproduces."
    )
    file_name: str = Field(
        default="test_repro.py", description="Target test file name."
    )
    code: str = Field(
        description="Self-contained Python pytest code that FAILS on buggy code."
    )
    explanation: str = Field(
        default="", description="Why this test proves the presence of the bug."
    )


class PatchProposal(BaseModel):
    """Structured unified diff patch proposal fixing the identified issue."""

    model_config = ConfigDict(frozen=True)

    file_path: str = Field(description="Relative path of the file being patched.")
    unified_diff: str = Field(
        description="Standard unified diff formatted patch string to apply with git apply."
    )
    rationale: str = Field(description="Explanation of the fix and why it is safe.")
    suggestion_block: str | None = Field(
        default=None,
        description="Optional GitHub suggestion code block if suitable for inline comment.",
    )
